-- UkweliSRHR — clickable resources per quick-answer (tap-to-call / open / jump in-app)
alter table public.ukweli_knowledge add column if not exists resources jsonb not null default '[]'::jsonb;

update public.ukweli_knowledge set resources = $j$[{"k": "app", "label": "Find a clinic", "v": "#fika"}, {"k": "call", "label": "One2One 1190", "v": "1190"}, {"k": "link", "label": "WHO: sexual health", "v": "https://www.who.int/health-topics/sexual-health"}]$j$::jsonb where slug like 'bodies-vary%';
